<script setup lang="ts">
import {ref,watch,computed} from 'vue'
import {downloadRows,downloadPage,type DownloadSort} from './downloadView'
import {transferRecovery} from './transferRecovery'
import {APP_VERSION} from './version'
import * as api from '../bindings/multipan/internal/desktop/desktopservice'
import type {DownloadJob,TransferSettings} from '../bindings/multipan/internal/transfer/models'
const props=defineProps<{view:'queue'|'settings';jobs:DownloadJob[];settings:TransferSettings}>()
const emit=defineEmits<{refresh:[];account:[id:string]}>()
const message=ref(''),busy=ref(false),query=ref(''),status=ref('all'),dirty=ref(false)
const queueKind=ref(''),queueSort=ref<DownloadSort>('newest'),queuePage=ref(1),queuePageSize=ref(50)
const selection=ref<string[]>([]),batchResults=ref<{id:string;name:string;applied:boolean;message:string}[]>([])
const pauseCount=computed(()=>props.jobs.filter(j=>['queued','running'].includes(j.status)).length)
const resumeCount=computed(()=>props.jobs.filter(j=>['paused','failed'].includes(j.status)).length)
async function controlAll(actionName:string){await action(async()=>{batchResults.value=await api.ControlAllQueuedDownloads(actionName)??[];selection.value=[]})}
async function clearPartials(){if(!chosen.value.length||busy.value)return;const ids=chosen.value.map(j=>j.id);await action(async()=>{batchResults.value=await api.ClearQueuedDownloadPartials(ids)??[];selection.value=[]})}
async function exportChosen(){if(!chosen.value.length||busy.value)return;const ids=chosen.value.map(j=>j.id);await action(async()=>{const path=await api.ExportQueuedDownloadReport(ids,APP_VERSION);message.value=path?'报告已保存到：'+path:'已取消保存报告'})}
const chosen=computed(()=>pageView.value.items.filter(j=>selection.value.includes(j.id)))
watch([query,status,queueKind,queueSort,queuePageSize],()=>{queuePage.value=1;selection.value=[]})
watch(queuePage,()=>selection.value=[])
function toggleJob(id:string,checked:boolean){if(busy.value)return;if(!checked)selection.value=selection.value.filter(x=>x!==id);else if(selection.value.length<200&&!selection.value.includes(id))selection.value.push(id)}
function selectJobs(checked:boolean){if(busy.value)return;selection.value=checked?pageView.value.items.map(j=>j.id):[]}
async function batch(actionName:string){if(!chosen.value.length||busy.value)return;const ids=chosen.value.map(j=>j.id);await action(async()=>{batchResults.value=await api.BatchQueuedDownloads(ids,actionName)??[];selection.value=[]})}
const form=ref({uploadConcurrency:3,downloadConcurrency:1,uploadKiB:0,downloadKiB:0,closeToTray:false})
watch(()=>props.settings,value=>{if(value&&!dirty.value)form.value={...value}},{immediate:true})
function cloudName(kind:string){return ({lanzou:'蓝奏云',quark:'夸克网盘',pan123:'123 云盘',baidu:'百度网盘',guangya:'光鸭云盘',ctdav:'诚通网盘',webdav:'WebDAV'} as Record<string,string>)[kind]??kind}
watch(()=>props.view,()=>{message.value='';selection.value=[]})
const labels:Record<string,string>={queued:'等待中',running:'下载中',paused:'已暂停',failed:'失败',saved:'已保存'}
const rows=computed(()=>downloadRows(props.jobs,status.value,queueKind.value,query.value,queueSort.value))
const queueKinds=computed(()=>[...new Set(props.jobs.map(j=>j.kind))].sort())
const pageView=computed(()=>downloadPage(rows.value,queuePage.value,queuePageSize.value))
watch(()=>pageView.value.page,value=>{if(queuePage.value!==value){queuePage.value=value;selection.value=[]}})
watch(()=>pageView.value.items.map(j=>j.id).join('\u0000'),()=>{const visible=new Set(pageView.value.items.map(j=>j.id));selection.value=selection.value.filter(id=>visible.has(id))})
function goQueuePage(value:number){if(!busy.value){selection.value=[];queuePage.value=downloadPage(rows.value,value,queuePageSize.value).page}}
function clearQueueFilters(){if(!busy.value){query.value='';status.value='all';queueKind.value='';queueSort.value='newest';queuePage.value=1;selection.value=[]}}
async function action(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;message.value='';try{await fn();emit('refresh')}catch(e){message.value=String(e)}finally{busy.value=false}}
async function copyChosen(){if(!chosen.value.length||busy.value)return;const snapshot=chosen.value.map(j=>({name:j.input.name,kind:cloudName(j.kind),destination:j.destination,status:labels[j.status]||j.status,message:j.message,result:j.result}));await action(async()=>{await api.CopyDownloadReport(snapshot.map(j=>['文件：'+j.name,'网盘：'+j.kind,'保存位置：'+j.destination,'状态：'+j.status,'说明：'+j.message,...(j.result?.details?['校验：'+j.result.details]:[])].join('\n')).join('\n\n'));message.value='所选下载结果已复制；发送前请检查文件名、本机路径和错误说明。'})}
async function save(){await action(async()=>{await api.SaveTransferSettings(form.value);dirty.value=false;message.value='传输设置已保存；降低并发时现有任务继续，后续调度按新上限运行。'})}
function recovery(job:DownloadJob){return transferRecovery('download',job.status,job.message)}
function bytes(n:number){return n<0?'未知大小':(n/1048576).toFixed(2)+' MB'}
</script>
<template>
<section v-if="view==='settings'" class="transfer-settings"><h1>传输设置</h1><form @submit.prevent="save" @input="dirty=true"><label>同时上传的账号数（每账号一个任务）<input v-model.number="form.uploadConcurrency" type="number" min="1" max="8" required/></label><label>同时下载的文件数<input v-model.number="form.downloadConcurrency" type="number" min="1" max="8" required/></label><label>上传限速 KiB/s（0 为不限速）<input v-model.number="form.uploadKiB" type="number" min="0" max="1048576" required/></label><label>下载限速 KiB/s（0 为不限速）<input v-model.number="form.downloadKiB" type="number" min="0" max="1048576" required/></label><label class="tray-setting"><input v-model="form.closeToTray" type="checkbox" @change="dirty=true"/>关闭窗口时隐藏到托盘，继续传输</label><button class="primary" :disabled="busy">保存设置</button></form></section>
<section v-else><div class="heading"><h1>下载队列与历史</h1><button class="secondary" :disabled="busy" @click="action(()=>api.ClearSavedDownloadHistory())">清理全部已保存记录</button></div><details class="operation-details"><summary>续传与清理</summary><p>节点支持续传且文件版本可确认时从断点继续，否则从头下载。下载保留已有文件，清理只移除本机记录。</p></details><div class="upload-task-actions"><button class="secondary" :disabled="busy||!pauseCount" @click="controlAll('pause')">暂停全部当前任务（{{pauseCount}}）</button><button class="secondary" :disabled="busy||!resumeCount" @click="controlAll('resume')">继续全部未完成（{{resumeCount}}）</button><span>全部操作包含筛选隐藏的任务。</span></div><div class="upload-task-filters"><input v-model="query" :disabled="busy" type="search" placeholder="搜索下载文件名或保存路径" aria-label="搜索持久下载任务"/><select v-model="status" :disabled="busy" aria-label="下载队列状态"><option value="all">全部状态</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select><select v-model="queueKind" :disabled="busy" aria-label="下载队列网盘类型"><option value="">所有网盘类型</option><option v-for="kind in queueKinds" :key="kind" :value="kind">{{cloudName(kind)}}</option></select><select v-model="queueSort" :disabled="busy" aria-label="下载队列排序"><option value="newest">最新任务优先</option><option value="oldest">最早任务优先</option><option value="name">文件名升序</option><option value="attention">失败 / 暂停优先</option></select><button class="secondary" :disabled="busy" @click="clearQueueFilters">重置筛选</button></div><div class="queue-pagination"><span role="status">匹配 {{rows.length}} / {{jobs.length}} 项 · 当前 {{pageView.first}}–{{pageView.last}} 项</span><label>每页<select v-model.number="queuePageSize" :disabled="busy" aria-label="下载队列每页项目数"><option :value="25">25项</option><option :value="50">50项</option><option :value="100">100项</option><option :value="200">200项</option></select></label><button class="secondary" :disabled="busy||pageView.page<=1" @click="goQueuePage(1)">首页</button><button class="secondary" :disabled="busy||pageView.page<=1" @click="goQueuePage(pageView.page-1)">上一页</button><span>第 {{pageView.page}} / {{pageView.pages}} 页</span><button class="secondary" :disabled="busy||pageView.page>=pageView.pages" @click="goQueuePage(pageView.page+1)">下一页</button></div><div v-if="rows.length" class="upload-task-actions"><label><input type="checkbox" :disabled="busy" :checked="chosen.length>0&&chosen.length===pageView.items.length" @change="selectJobs(($event.target as HTMLInputElement).checked)"/>选择当前页任务</label><span>已选 {{chosen.length}} 项</span><button class="secondary" :disabled="busy||!chosen.length" @click="batch('pause')">暂停所选</button><button class="secondary" :disabled="busy||!chosen.length" @click="batch('resume')">继续所选</button><button class="secondary" :disabled="busy||!chosen.length" @click="batch('remove')">移除所选记录</button><button class="secondary" :disabled="busy||!chosen.length" @click="copyChosen">复制所选结果</button><button class="secondary" :disabled="busy||!chosen.length" @click="exportChosen">导出所选报告</button><button class="secondary" :disabled="busy||!chosen.length" @click="clearPartials">清理所选续传临时文件</button></div><p class="preview-note">排序只改变显示，下载执行顺序保持原队列顺序。翻页或更改筛选会清除选择。</p><p>移除记录不删除已下载或临时文件，但会放弃这些记录的续传入口。进行中或排队的任务需先暂停。清理续传临时文件后，下次继续将从头下载，正式文件不受影响。</p><details v-if="batchResults.length" open class="upload-batch-results"><summary>最近批量操作结果</summary><p v-if="batchResults.length>200">共 {{batchResults.length}} 项结果，下方显示前200项。</p><ul><li v-for="(result,i) in batchResults.slice(0,200)" :key="i">{{result.name||'已失效任务'}}：{{result.message}}</li></ul></details><p v-if="!rows.length">暂无匹配的下载任务。</p><article v-for="job in pageView.items" :key="job.id" class="task-row"><label class="queue-selection"><input type="checkbox" :aria-label="'选择下载任务：'+job.input.name" :checked="selection.includes(job.id)" :disabled="busy||(!selection.includes(job.id)&&selection.length>=200)" @change="toggleJob(job.id,($event.target as HTMLInputElement).checked)"/><strong>{{job.input.name}}</strong></label><span class="status">{{labels[job.status]||job.status}}</span><p class="transfer-local-path">{{cloudName(job.kind)}} · {{job.destination}}</p><p>{{bytes(job.received)}} / {{bytes(job.total)}} · {{job.message}}</p><progress class="queue-progress" v-if="job.total>0" :value="job.received" :max="job.total" :aria-label="job.input.name+'队列下载进度'"/><div v-if="recovery(job)" class="transfer-recovery"><strong>{{recovery(job)?.title}}</strong><p>{{recovery(job)?.detail}}</p><button v-if="recovery(job)?.kind==='auth'" class="secondary small" :disabled="busy" @click="emit('account',job.input.accountId)">更新此网盘登录</button></div><p v-if="job.result?.verification">{{job.result.verification==='verified'?'校验通过':'已保存，完整性未验证'}} · {{job.result.details}}</p><div class="saved-location-actions"><button v-if="job.status==='queued'||job.status==='running'" class="secondary" :disabled="busy" @click="action(()=>api.ControlQueuedDownload(job.id,false))">暂停</button><button v-if="job.status==='paused'||job.status==='failed'" class="secondary" :disabled="busy" @click="action(()=>api.ControlQueuedDownload(job.id,true))">继续 / 重试</button><button v-if="job.status==='saved'" class="secondary" :disabled="busy" @click="action(()=>api.OpenQueuedDownloadFolder(job.id))">打开保存文件夹</button></div></article></section><p v-if="message" role="status" class="banner notice">{{message}}</p>
</template>
